/bin/bash -lc "cat > index.html <<'EOF'
<"'!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width, initial-scale=1">
  <meta name="theme-color" content="#f9f8f3">
  <meta name="description" content="Lemon ricotta pancakes for four, ready in 25 minutes. A simple recipe with creamy ricotta and fresh lemon zest.">
  <title>Lemon ricotta pancakes · The Sunday Table</title>
  <link rel="preconnect" href="https://fonts.googleapis.com">
  <link rel="preconnect" href="https://fonts.gstatic.com" crossorigin>
  <link href="https://fonts.googleapis.com/css2?family=DM+Sans:wght@400;500;600&family=DM+Serif+Display&display=swap" rel="stylesheet">
  <style>
    :root {
      color-scheme: light;
      --color-paper: #f9f8f3;
      --color-ink: #292e24;
      --color-muted: #66695c;
      --color-olive: #4a5637;
      --color-olive-hover: #354027;
      --color-panel: #eeefe5;
      --color-line: #d9dacd;
      --color-control: #858975;
      --color-white: #fff;
      --font-body: '"'DM Sans', sans-serif;
      --font-display: 'DM Serif Display', Georgia, serif;
      --text-sm: .8125rem;
      --text-base: 1rem;
      --text-body: 1.0625rem;
      --text-lg: 1.25rem;
      --text-heading: 2rem;
      --space-1: 4px; --space-2: 8px; --space-3: 12px; --space-4: 16px;
      --space-6: 24px; --space-8: 32px; --space-12: 48px; --space-16: 64px; --space-24: 96px;
      --radius: 4px;
    }
    *, *::before, *::after { box-sizing: border-box; }
    html { scroll-behavior: smooth; scroll-padding-top: var(--space-8); }
    body { margin: 0; background: var(--color-paper); color: var(--color-ink); font: var(--text-base)/1.6 var(--font-body); -webkit-font-smoothing: antialiased; }
    button, input { font: inherit; }
    a { color: inherit; }
    button, a, input { -webkit-tap-highlight-color: transparent; }
    a:focus-visible, button:focus-visible, input:focus-visible { outline: 2px solid var(--color-olive); outline-offset: 5px; }
    button, a { touch-action: manipulation; }
    button { cursor: pointer; }
    svg { display: block; flex-shrink: 0; }
    .page { width: min(1248px, calc(100% - 128px)); margin-inline: auto; }
    .skip-link { position: fixed; top: 8px; left: 8px; z-index: 10; padding: 12px 24px; background: var(--color-paper); transform: translateY(-150%); }
    .skip-link:focus { transform: translateY(0); }
    .site-header { height: 112px; display: flex; align-items: center; justify-content: space-between; border-bottom: 1px solid var(--color-line); gap: var(--space-6); }
    .brand { display: flex; align-items: center; gap: var(--space-3); font: 1.75rem/1.1 var(--font-display); text-decoration: none; letter-spacing: -.04em; }
    .brand svg { width: 36px; height: 40px; color: var(--color-olive); }
    .header-note { color: var(--color-muted); font-size: var(--text-sm); }
    .header-note span { display: inline-block; width: 5px; height: 5px; border-radius: 50%; background: var(--color-olive); margin: 0 12px 2px; }
    .hero { display: grid; grid-template-columns: 1fr 1fr; gap: var(--space-16); padding-block: var(--space-12) var(--space-16); align-items: center; }
    .hero-copy { padding-block: var(--space-6); }
    .category { display: flex; align-items: center; gap: var(--space-3); margin: 0 0 var(--space-6); color: var(--color-olive); font-size: var(--text-sm); font-weight: 600; letter-spacing: .12em; text-transform: uppercase; }
    .category::before { content: ''; width: 28px; height: 1px; background: currentColor; }
    h1, h2, h3, p { margin-top: 0; }
    h1, h2, h3 { font-family: var(--font-display); font-weight: 400; text-wrap: balance; }
    h1 { font-size: clamp(3.5rem, 5.5vw, 5rem); line-height: 1.04; letter-spacing: -.035em; margin-bottom: var(--space-6); }
    .intro { font-size: var(--text-body); color: var(--color-muted); max-width: 38ch; margin-bottom: var(--space-8); line-height: 1.75; }
    .recipe-meta { display: flex; gap: var(--space-6); align-items: center; margin-bottom: var(--space-8); }
    .meta-item { display: flex; align-items: center; gap: var(--space-3); font-size: .9375rem; }
    .meta-item svg { width: 20px; height: 20px; color: var(--color-olive); }
    .meta-item + .meta-item { padding-left: var(--space-6); border-left: 1px solid var(--color-line); }
    .hero-actions { display: flex; gap: var(--space-6); align-items: center; flex-wrap: wrap; }
    .button { display: inline-flex; align-items: center; justify-content: center; gap: var(--space-3); min-height: 48px; border: 1px solid transparent; border-radius: var(--radius); font-size: .875rem; font-weight: 500; text-decoration: none; transition: background 150ms, color 150ms; }
    .button svg { width: 18px; height: 18px; }
    .button-primary { background: var(--color-olive); color: var(--color-white); padding: var(--space-3) var(--space-6); }
    .button-primary:hover { background: var(--color-olive-hover); }
    .button-primary:active { transform: translateY(1px); }
    .button-print { padding: var(--space-3) 0; background: transparent; color: var(--color-ink); }
    .button-print:hover { color: var(--color-olive); text-decoration: underline; text-underline-offset: 4px; }
    .hero-figure { margin: 0; position: relative; }
    .hero-image { display: block; width: 100%; height: 576px; object-fit: cover; border-radius: var(--radius); background: var(--color-panel); }
    .recipe { border-top: 1px solid var(--color-line); padding-block: var(--space-12) var(--space-16); scroll-margin-top: var(--space-8); }
    .recipe-heading { display: flex; align-items: baseline; justify-content: space-between; gap: var(--space-6); margin-bottom: var(--space-8); }
    .recipe-heading h2 { font-size: 2.5rem; line-height: 1.15; letter-spacing: -.025em; margin: 0; }
    .recipe-heading p { font-size: var(--text-sm); color: var(--color-muted); margin: 0; }
    .recipe-grid { display: grid; grid-template-columns: 400px 1fr; gap: var(--space-16); align-items: start; }
    .ingredients { background: var(--color-panel); padding: var(--space-8); border-radius: var(--radius); }
    .ingredients-header { display: flex; align-items: baseline; justify-content: space-between; gap: var(--space-4); margin-bottom: var(--space-4); }
    h3 { font-size: var(--text-heading); line-height: 1.2; letter-spacing: -.025em; margin-bottom: var(--space-6); }
    .ingredients-header h3 { margin: 0; }
    .ingredients-header span { color: var(--color-muted); font-size: var(--text-sm); white-space: nowrap; }
    .ingredient-list { list-style: none; padding: 0; margin: 0; }
    .ingredient-list li + li { border-top: 1px solid var(--color-line); }
    .ingredient { display: flex; align-items: center; gap: var(--space-3); min-height: 48px; cursor: pointer; font-size: .9375rem; line-height: 1.5; padding-block: var(--space-3); }
    .ingredient input { appearance: none; width: 18px; height: 18px; margin: 0; border: 1px solid var(--color-control); border-radius: 2px; background: transparent; flex: 0 0 18px; cursor: pointer; display: grid; place-content: center; }
    .ingredient input::before { content: ''; width: 9px; height: 5px; border: solid var(--color-white); border-width: 0 0 2px 2px; transform: translateY(-1px) rotate(-45deg) scale(0); }
    .ingredient input:checked { background: var(--color-olive); border-color: var(--color-olive); }
    .ingredient input:checked::before { transform: translateY(-1px) rotate(-45deg) scale(1); }
    .ingredient input:checked + span { color: var(--color-muted); text-decoration: line-through; }
    .ingredient:hover input { border-color: var(--color-olive); }
    .ingredient strong { font-weight: 600; }
    .method { padding-top: var(--space-1); }
    .steps { list-style: none; padding: 0; margin: 0; counter-reset: steps; }
    .steps li { display: grid; grid-template-columns: 40px 1fr; gap: var(--space-4); counter-increment: steps; padding-bottom: var(--space-6); }
    .steps li + li { padding-top: var(--space-6); border-top: 1px solid var(--color-line); }
    .steps li::before { content: '0' counter(steps); color: var(--color-olive); font: 1.5rem/1.3 var(--font-display); }
    .step-title { display: block; font-weight: 600; margin-bottom: var(--space-1); }
    .steps p { margin: 0; color: var(--color-muted); font-size: var(--text-base); line-height: 1.7; max-width: 58ch; }
    footer { display: flex; justify-content: space-between; gap: var(--space-6); padding-block: var(--space-6) var(--space-8); border-top: 1px solid var(--color-line); color: var(--color-muted); font-size: var(--text-sm); }
    footer .footer-brand { font-family: var(--font-display); font-size: 1.125rem; color: var(--color-ink); }
    @media (min-width: 1500px) { .hero-image { height: 608px; } }
    @media (max-width: 1100px) {
      .page { width: calc(100% - 80px); }
      .hero { gap: var(--space-8); }
      h1 { font-size: clamp(3rem, 5.7vw, 4rem); }
      .hero-image { height: 520px; }
      .recipe-grid { grid-template-columns: minmax(300px, .8fr) 1fr; gap: var(--space-8); }
      .ingredients { padding: var(--space-6); }
      .recipe-heading p { max-width: 24ch; text-align: right; }
    }
    @media (max-width: 700px) {
      .page { width: calc(100% - 40px); }
      .site-header { height: 88px; }
      .brand { font-size: 1.5rem; }
      .brand svg { width: 28px; height: 32px; }
      .header-note { display: none; }
      .hero { grid-template-columns: 1fr; gap: var(--space-8); padding-block: var(--space-8) var(--space-12); }
      .hero-copy { padding-block: 0; }
      .category { margin-bottom: var(--space-4); font-size: .75rem; }
      h1 { font-size: clamp(3.25rem, 11vw, 4.5rem); max-width: 12ch; margin-bottom: var(--space-4); }
      .intro { margin-bottom: var(--space-6); max-width: 42ch; }
      .recipe-meta { margin-bottom: var(--space-6); }
      .hero-image { height: auto; aspect-ratio: 1.08; object-position: 50% 57%; }
      .recipe { padding-block: var(--space-8) var(--space-12); }
      .recipe-heading { display: block; margin-bottom: var(--space-6); }
      .recipe-heading h2 { font-size: 2.25rem; margin-bottom: var(--space-2); }
      .recipe-heading p { text-align: left; max-width: none; }
      .recipe-grid { grid-template-columns: 1fr; gap: var(--space-8); }
      .ingredients { padding: var(--space-6); }
      h3 { font-size: 1.75rem; }
      .ingredient { min-height: 48px; }
      .steps li { grid-template-columns: 32px 1fr; gap: var(--space-3); }
      footer { align-items: baseline; }
    }
    @media (prefers-reduced-motion: reduce) { html { scroll-behavior: auto; } *, *::before, *::after { transition: none "'!important; } }
    @media print {
      :root { --color-paper: #fff; --color-ink: #000; --color-muted: #333; --color-line: #ccc; --color-panel: #fff; }
      body { font-size: 10pt; }
      .page { width: 100%; }
      .site-header { height: auto; padding-bottom: 16px; }
      .header-note, .hero-figure, .hero-actions, .skip-link, .recipe-heading p, footer { display: none; }
      .hero { display: block; padding: 24px 0; }
      .hero-copy { padding: 0; }
      .category { margin-bottom: 8px; }
      h1 { font-size: 36pt; margin-bottom: 12px; }
      .intro { max-width: none; margin-bottom: 12px; }
      .recipe-meta { margin: 0; }
      .recipe { padding: 24px 0; }
      .recipe-heading { margin-bottom: 24px; }
      .recipe-grid { grid-template-columns: 35% 1fr; gap: 32px; }
      .ingredients { padding: 0; }
      h3 { font-size: 20pt; }
      .ingredients-header { display: block; }
      .ingredient { min-height: 0; padding: 8px 0; font-size: 10pt; }
      .ingredient input { display: none; }
      .ingredient input:checked + span { text-decoration: none; color: var(--color-ink); }
      .steps li { break-inside: avoid; padding-bottom: 16px; }
      .steps li + li { padding-top: 16px; }
      .steps p { font-size: 10pt; }
      .hero, .recipe-grid { break-inside: avoid; }
    }
  </style>
